UPDATE users
   SET nickname      = #{nickname},
       phone         = #{phone},
       profile_image = #{profileImage}
 WHERE id = #{id}

UPDATE users
   SET is_banned = #{isBanned},
       banned_at = CASE WHEN #{isBanned} THEN NOW() ELSE NULL END,
       banned_reason = #{reason}
 WHERE id = #{id}

